INSERT DBObjects VALUES('mos_allstar_dr17_synspec_rev1','U','U','The APOGEE All-Star DR17 synspec catalogue.','','0');
INSERT DBObjects VALUES('mos_allwise','U','U','ALLWISE catalog: https://wise2.ipac.caltech.edu/docs/release/allwise/. For detailed descriptions of the columns see: https://wise2.ipac.caltech.edu/docs/release/allwise/expsup/sec2_1a.html','','0');
INSERT DBObjects VALUES('mos_assignment','U','U','This table stores the assignment of a given target in a carton to a fiber of a given instrument. A collection of assignments are included within a design, which is one configuration of the robots for an exposure.','','0');
INSERT DBObjects VALUES('mos_bailer_jones_edr3','U','U','Geometric and photogeometric distances to 1.47 billion stars in Gaia Early Data Release 3 from Bailer-Jones et al. (2021) (see https://ui.adsabs.harvard.edu/abs/2021AJ....161..147B/abstract).','','0');
INSERT DBObjects VALUES('mos_best_brightest','U','U','Catalog for the selection of bright metal-poor stars from the method of Schlaufman and Casey (2014): https://ui.adsabs.harvard.edu/abs/2014ApJ...797...13S/abstract. WISE values from WHICH CATALOG, 2MASS values from 2MASS point source catalog.','','0');
INSERT DBObjects VALUES('mos_bhm_csc','U','U','Chandra Source Catalogue version 2.0 (CSC2) sources.','Chandra Source Catalogue version 2.0 (CSC2) sources that have been matched (separately) to the PanSTARRS-1 and 2MASS catalogs.  This version of the CSC2 catalog informed early (plate era) SDSS-V observations but was then replaced by updated versions.','0');
INSERT DBObjects VALUES('mos_bhm_csc_v2','U','U','CSC2 X-ray sources.','This catalogue contains CSC2 X-ray sources that have been matched separately to PanSTARRS-1, Gaia DR2, and 2MASS catalogs, using the programs NWAY (Johannes Buchner; see: Salvato 2018, MN, 473, 4937) and Xmatch (Arnold Rots; see: https://cxc.cfa.harvard.edu/csc/csc_crossmatches.html). Both are based on the Bayesian spatial cross-matching algorithm developed by Budavari & Szalay (2008, ApJ 679, 301), but Xmatch has the added capability of taking source extent and/or PSF into account. Created March 2021 by Paul Green, Dong-Woo Kim, Arnold Rots and the CXC CatSci group.','0');
INSERT DBObjects VALUES('mos_bhm_csc_v3','U','U','Chandra Source Catalog (CSC) 2.1 Optical/IR Counterparts Catalog','2022 Dec. See https://asc.harvard.edu/csc2.1/index.html for the CSC 2.1 release notes and documentation.','0');
INSERT DBObjects VALUES('mos_bhm_efeds_veto','U','U','The BHM-SPIDERS eFEDS veto catalogue.','A minimalist catalogue of 6300 science targets in the SPIDERS eFEDS field that received SDSS-IV spectroscopy during the March2020 SPIDERS observing run (and hence are not in SDSS-SpecObj-DR16). Many of these spectra have very low SNR and so we will want to observe them again, but we will take account of this in the Carton code. This is a subset (in both rows and columns) of the spAll-v5_13_1.fits idlspec2d pipeline product. The original data model for that file is here: https://data.sdss.org/datamodel/files/BOSS_SPECTRO_REDUX/RUN2D/spAll.html','0');
INSERT DBObjects VALUES('mos_bhm_rm_tweaks','U','U','Reverberation mapping (RM) targets for SDSS-V.','This table enables small modifications to be made to the set of reverberation mapping (RM) targets selected for observation in SDSS-V. The dr20_bhm_rm_tweaks table allows identification of confirmed QSOs which were observed in plate mode that should be preferentially targeted in forward-looking FPS mode observations, and reject candidates which the plate-mode observations have revealed to be unsuitable for continued RM studies.','0');
INSERT DBObjects VALUES('mos_bhm_rm_v0','U','U','Parent sample for the RM project.','Used to select confirmed and candidate quasar targets for the BHM-RM Program in SDSS-V. For more details please see Yang and Shen, (2022, https://ui.adsabs.harvard.edu/abs/2022arXiv220608989Y/abstract). <br> This table contains all photometric objects detected in the COSMOS, SDSS-RM, XMM-LSS, CDFS, S-CVZ, and ELAIS-S1 fields., within a circular area of 10 degree^2 from the field center. <br> Field center: Name     RA          DEC <br> XMM-LSS  02:22:50.00    -04:45:00.0 <br> CDFS     03:30:35.60    -28:06:00.0 <br> EDFS     04:04:57.84    -48:25:22.8 <br> ELAIS-S1 00:37:48.00    -44:00:00.0 <br> COSMOS   10:00:00.00    +02:12:00.0 <br> SDSS-RM  14:14:49.00    +53:05:00.0 <br> S-CVZ    06:00:00.00    -66:33:38.0 <br> The table includes information from the following survey data releases: <br> DES: Dark Energy Survey, Y6, Y6A1_COADD_OBJECT_SUMMARY <br> PS1: Pan-STARRS, DR1, StackObjectThin <br> NSC: NOAO Source Catalog, DR1, nsc_dr1.object <br> SDSS: Sloan Digital Sky Survey, DR14, PhotoObjAll <br> Gaia: DR2, gaia_dr2.gaia_source <br> unWISE: DR1 <br> Near-infrared: LAS: UKIDSS Large Area Surveys (DR11), <br> UHS: UKIRT Hemisphere Survey (DR1), <br> VHS: VISTA Hemisphere Survey (DR6), <br> Viking: VISTA Kilo-Degree Infrared Galaxy Survey (DR5), <br> VIDEO: VISTA Deep Extragalactic Observations Survey (DR5), <br> VMC: VISTA Magellanic Cloud Survey (DR4) <br> Values are set to -9.0 or -9 if null. <br> The dr20_bhm_rm_v0 table corresponds to Version: v0, 04/07/2020 <br> Note that contents of the spec_q column are incorrect in this version of the table.','0');
INSERT DBObjects VALUES('mos_bhm_rm_v0_2','U','U','Parent sample for the RM project.','Used to select confirmed and candidate quasar targets for the BHM-RM Program in SDSS-V. For more details please see Yang and Shen, (2022, https://ui.adsabs.harvard.edu/abs/2022arXiv220608989Y/abstract). <br> This table contains all photometric objects detected in the COSMOS, SDSS-RM, XMM-LSS, CDFS, S-CVZ, and ELAIS-S1 fields., within a circular area of 10 degree^2 from the field center. <br> Field center: Name     RA          DEC <br> XMM-LSS  02:22:50.00    -04:45:00.0 <br> CDFS     03:30:35.60    -28:06:00.0 <br> EDFS     04:04:57.84    -48:25:22.8 <br> ELAIS-S1 00:37:48.00    -44:00:00.0 <br> COSMOS   10:00:00.00    +02:12:00.0 <br> SDSS-RM  14:14:49.00    +53:05:00.0 <br> S-CVZ    06:00:00.00    -66:33:38.0 <br> The table includes information from the following survey data releases: <br> DES: Dark Energy Survey, Y6, Y6A1_COADD_OBJECT_SUMMARY <br> PS1: Pan-STARRS, DR1, StackObjectThin <br> NSC: NOAO Source Catalog, DR1, nsc_dr1.object <br> SDSS: Sloan Digital Sky Survey, DR14, PhotoObjAll <br> Gaia: DR2, gaia_dr2.gaia_source <br> unWISE: DR1 <br> Near-infrared: LAS: UKIDSS Large Area Surveys (DR11), <br> UHS: UKIRT Hemisphere Survey (DR1), <br> VHS: VISTA Hemisphere Survey (DR6), <br> Viking: VISTA Kilo-Degree Infrared Galaxy Survey (DR5), <br> VIDEO: VISTA Deep Extragalactic Observations Survey (DR5), <br> VMC: VISTA Magellanic Cloud Survey (DR4) <br> Values are set to -9.0 or -9 if null. <br> The dr20_bhm_rm_v0_2 table corresponds to Version: v0.2, 06/30/2020 <br> Changes (wrt v0) include correct error in spec_q column, and add specz from OzDES DR2','0');
INSERT DBObjects VALUES('mos_bhm_rm_v1','U','U','arent sample for the RM project.','Used to select confirmed and candidate quasar targets for the BHM-RM Program in SDSS-V. For more details please see Yang and Shen, (2022, https://ui.adsabs.harvard.edu/abs/2022arXiv220608989Y/abstract). <br> This table contains all photometric objects detected in the COSMOS, SDSS-RM, XMM-LSS, CDFS, S-CVZ, and ELAIS-S1 fields., within a circular area of 10 degree^2 from the field center. <br> Field center: Name     RA          DEC <br> XMM-LSS  02:22:50.00    -04:45:00.0 <br> CDFS     03:30:35.60    -28:06:00.0 <br> EDFS     04:04:57.84    -48:25:22.8 <br> ELAIS-S1 00:37:48.00    -44:00:00.0 <br> COSMOS   10:00:00.00    +02:12:00.0 <br> SDSS-RM  14:14:49.00    +53:05:00.0 <br> S-CVZ    06:00:00.00    -66:33:38.0 <br> The table includes information from the following survey data releases: <br> PS1: Pan-STARRS, DR1, StackObjectThin <br> SDSS: Sloan Digital Sky Survey, DR14, PhotoObjAll <br> Gaia: DR2, gaia_dr2.gaia_source, DR3, gaia_dr3.gaia_source <br> Legacy Survey DR8 and DR10. <br> Values are set to -9.0 or -9 if null. <br> The dr20_bhm_rm_v1 table corresponds to Version: v1, 11/29/2022','0');
