INSERT DBObjects VALUES('mos_bhm_spiders_agn_superset','U','U','One of several tables describing optical/IR counterparts to eROSITA','X-ray sources identified via various methods. <br> These tables contain a superset of potential targets from which the SDSS-V spectroscopic targets were drawn.  The dr20_bhm_spiders_agn_superset table includes is expected to be dominated by Active Galactic Nuclei (AGN) but should also include a significant minority of galaxies, stars and other Galactic sources. Each row corresponds to one possible match between an X-ray source and a potential optical/IR counterpart.  The X-ray columns (ero_*) record the eROSITA information known at the time of target selection and may differ from publicly available eROSITA catalogs. The dr20_bhm_spiders_*_superset tables are derived from eROSITA observations of the eROSITA Final Equatorial Depth performance verification field (''eFEDS'').','0');
INSERT DBObjects VALUES('mos_bhm_spiders_clusters_superset','U','U','One of several tables describing optical/IR counterparts to eROSITA','X-ray sources identified via various methods. <br> These tables contain a superset of potential targets from which the SDSS-V spectroscopic targets were drawn.  The dr20_bhm_spiders_clusters_superset table includes counterparts selected via algorithms optimised to find clusters of galaxies. Each row corresponds to one possible match between an X-ray source and a potential optical/IR counterpart.  The X-ray columns (ero_*) record the eROSITA information known at the time of target selection and may differ from publicly available eROSITA catalogs. The dr20_bhm_spiders_*_superset tables are derived from eROSITA observations of the eROSITA Final Equatorial Depth performance verification field (''eFEDS'').','0');
