INSERT DBObjects VALUES('mos_cataclysmic_variables','U','U','Gaia DR2 parameters for AAVSO cataclysmic variables from cataclysmic (explosive and nova-like) variables (N, NA, NB, NC, NL, NR, SN, SNI, SNII, UG, UGSS, UGSU, UGZ, ZAND). VSX catalog downloaded in summer 2019 and then manually pruned.','','0');
INSERT DBObjects VALUES('mos_catalog','U','U','The results of the cross-match used for DR20 targeting. Entries in this table are expected to be unique physical objects drawn from one or more parent catalogues. The dr20_catalog_to_ tables provide the relationships to their parent catalogue counterparts.','','0');
INSERT DBObjects VALUES('mos_catalog_from_sdss_dr19p_speclite','U','U','Relational table linking dr20_catalog with dr20_sdss_dr19p_speclite.','Although this table has the same columns and purpose of other [catalog_to_X] tables in this schema, it is explicitly named [catalog_from] as it was generated using a bespoke cross-match different from the usual process used for other cross-matched tables in DR20.','0');
