INSERT DBObjects VALUES('mos_ebosstarget_v5','U','U','A catalog of targets, selected from SDSS+WISE imaging that were considered for observation in the SDSS-IV/eBOSS project, including spectrophotometric starts and candidate QSOs.','This catalogue is a data product of the ebosstarget target selection software, version [v5_0].','0');
INSERT DBObjects VALUES('mos_erosita_superset_agn','U','U','One of several tables describing optical/IR counterparts to eROSITA','X-ray sources identified via various methods. <br> These tables contain a superset of potential targets from which the SDSS-V spectroscopic targets were drawn.  The dr20_erosita_superset_agn table includes counterparts to point-like X-ray sources. The sample is expected to be dominated by Active Galactic Nuclei (AGN) but should also include a significant minority of galaxies, stars and other Galactic sources. Each row corresponds to one possible match between an X-ray source and a potential optical/IR counterpart. The X-ray columns (ero_*) record the eROSITA information known at the time of target selection and may differ from publicly available eROSITA catalogs. The dr20_erosita_superset_* tables are derived from a combination of eROSITA''s first 6-month survey of of the West Galactic hemisphere (''eRASS1''), and from the eROSITA observations of the eROSITA Final Equatorial Depth performance verification field (''eFEDS'').','0');
INSERT DBObjects VALUES('mos_erosita_superset_clusters','U','U','One of several tables describing optical/IR counterparts to eROSITA','X-ray sources identified via various methods. <br> These tables contain a superset of potential targets from which the SDSS-V spectroscopic targets were drawn. The dr20_erosita_superset_clusters table includes counterparts to both extended and point-like X-ray sources, selected via algorithms optimised to find clusters of galaxies.  Each row corresponds to one possible match between an X-ray source and a potential optical/IR counterpart.  The X-ray columns (ero_*) record the eROSITA information known at the time of target selection and may differ from publicly available eROSITA catalogs. The dr20_erosita_superset_* tables are derived from a combination of eROSITA''s first 6-month survey of of the West Galactic hemisphere (''eRASS1''), and from the eROSITA observations of the eROSITA Final Equatorial Depth performance verification field (''eFEDS'').','0');
INSERT DBObjects VALUES('mos_erosita_superset_compactobjects','U','U','One of several tables describing optical/IR counterparts to eROSITA','X-ray sources identified via various methods. <br> These tables contain a superset of potential targets from which the SDSS-V spectroscopic targets were drawn. The dr20_erosita_superset_agn table includes counterparts to point-like X-ray sources, chosen via algorithms optimised to select compact objects. Each row corresponds to one possible match between an X-ray source and a potential optical/IR counterpart. The X-ray columns (ero_*) record the eROSITA information known at the time of target selection and may differ from publicly available eROSITA catalogs. The dr20_erosita_superset_* tables are derived from a combination of eROSITA''s first 6-month survey of of the West Galactic hemisphere (''eRASS1''), and from the eROSITA observations of the eROSITA Final Equatorial Depth performance verification field (''eFEDS'').','0');
INSERT DBObjects VALUES('mos_erosita_superset_stars','U','U','One of several tables describing optical/IR counterparts to eROSITA','X-ray sources identified via various methods. <br> These tables contain a superset of potential targets from which the SDSS-V spectroscopic targets were drawn. The dr20_erosita_superset_stars table includes counterparts to point-like X-ray sources, chosen via an algorithm optimised to select coronally active stars. Each row corresponds to one possible match between an X-ray source and a potential optical/IR counterpart. The X-ray columns (ero_*) record the eROSITA information known at the time of target selection and may differ from publicly available eROSITA catalogs. The dr20_erosita_superset_* tables are derived from a combination of eROSITA''s first 6-month survey of of the West Galactic hemisphere (''eRASS1''), and from the eROSITA observations of the eROSITA Final Equatorial Depth performance verification field (''eFEDS'').','0');
INSERT DBObjects VALUES('mos_erosita_superset_v1_agn','U','U','One of several tables describing optical/IR counterparts to eROSITA','X-ray sources identified via various methods. <br> These tables contain a superset of potential targets from which the SDSS-V spectroscopic targets were drawn.  The dr20_erosita_superset_v1_agn table includes counterparts to point-like X-ray sources. The sample is expected to be dominated by Active Galactic Nuclei (AGN) but should also include a significant minority of galaxies, stars and other Galactic sources. Each row corresponds to one possible match between an X-ray source and a potential optical/IR counterpart.  The X-ray columns (ero_*) record the eROSITA information known at the time of target selection and may differ from publicly available eROSITA catalogs. The dr20_erosita_superset_v1* tables are derived from a combination of eROSITA''s first 6-month survey of of the West Galactic hemisphere (''eRASS1''), and from the eROSITA observations of the eROSITA Final Equatorial Depth performance verification field (''eFEDS'').','0');
INSERT DBObjects VALUES('mos_erosita_superset_v1_clusters','U','U','One of several tables describing optical/IR counterparts to eROSITA','X-ray sources identified via various methods. <br> These tables contain a superset of potential targets from which the SDSS-V spectroscopic targets were drawn. The dr20_erosita_superset_v1_clusters table includes counterparts to both extended and point-like X-ray sources, selected via algorithms optimised to find clusters of galaxies.  Each row corresponds to one possible match between an X-ray source and a potential optical/IR counterpart.  The X-ray columns (ero_*) record the eROSITA information known at the time of target selection and may differ from publicly available eROSITA catalogs. The dr20_erosita_superset_v1* tables are derived from a combination of eROSITA''s first 6-month survey of of the West Galactic hemisphere (''eRASS1''), and from the eROSITA observations of the eROSITA Final Equatorial Depth performance verification field (''eFEDS'').','0');
INSERT DBObjects VALUES('mos_erosita_superset_v1_compactobjects','U','U','One of several tables describing optical/IR counterparts to eROSITA','X-ray sources identified via various methods. <br> These tables contain a superset of potential targets from which the SDSS-V spectroscopic targets were drawn. The dr20_erosita_superset_v1_compactobjects table includes counterparts to point-like X-ray sources, chosen via algorithms optimised to select compact objects. Each row corresponds to one possible match between an X-ray source and a potential optical/IR counterpart. The X-ray columns (ero_*) record the eROSITA information known at the time of target selection and may differ from publicly available eROSITA catalogs. The dr20_erosita_superset_v1* tables are derived from a combination of eROSITA''s first 6-month survey of of the West Galactic hemisphere (''eRASS1''), and from the eROSITA observations of the eROSITA Final Equatorial Depth performance verification field (''eFEDS'').','0');
INSERT DBObjects VALUES('mos_erosita_superset_v1_stars','U','U','One of several tables describing optical/IR counterparts to eROSITA','X-ray sources identified via various methods. <br> These tables contain a superset of potential targets from which the SDSS-V spectroscopic targets were drawn. The dr20_erosita_superset_v1_stars table includes counterparts to point-like X-ray sources, chosen via an algorithm optimised to select coronally active stars. Each row corresponds to one possible match between an X-ray source and a potential optical/IR counterpart. The X-ray columns (ero_*) record the eROSITA information known at the time of target selection and may differ from publicly available eROSITA catalogs. The dr20_erosita_superset_v1* tables are derived from a combination of eROSITA''s first 6-month survey of of the West Galactic hemisphere (''eRASS1''), and from the eROSITA observations of the eROSITA Final Equatorial Depth performance verification field (''eFEDS'').','0');
INSERT DBObjects VALUES('mos_field','U','U','The table includes the field information, where a field is a unique pointing of the telescope on the sky.','','0');
INSERT DBObjects VALUES('mos_gaia_assas_sn_cepheids','U','U','Well-defined and characterized all-sky sample of classical Cepheids in the Milky Way presented in Inno+2021.','The sample is obtained by combining two time-domain all-sky surveys: Gaia DR2 (Gaia Col. 2018; see I/345) and All-Sky Automated Survey for Supernovae (ASAS- SN; Shappee+ 2014AAS...22323603S). Inno+21 use parallax and variability information from Gaia  to select ~30000 bright (G<17) Cepheid candidates with M_K_{<}-1. They analyze their ASAS-SN V-band light curves, determining periods and classifying the light curves using their Fourier parameters. This results in ~1900 likely Galactic Cepheids, Inno+21 estimate to be >~90% complete and pure within their adopted selection criteria.','0');
INSERT DBObjects VALUES('mos_gaia_dr2_ruwe','U','U','Table from Gaia DR2 containing the Renormalised Unit Weight Error (RUWE) associated to each source in gaia_source.','See https://gea.esac.esa.int/archive/documentation/GDR2/Gaia_archive/chap_datamo del/sec_dm_main_tables/ssec_dm_ruwe.html for more detailed descriptions of the columns','0');
INSERT DBObjects VALUES('mos_gaia_dr2_source','U','U','Gaia DR2 Source Table.','See https://gea.esac.esa.int/archive/documentation/GDR2/Gaia_archive/chap_datamo del/sec_dm_main_tables/ssec_dm_gaia_source.html for complete details.','0');
INSERT DBObjects VALUES('mos_gaia_dr2_wd','U','U','White dwarf catalog of high-probablity WDs from Gentile Fusillo (2019) based on Gaia DR2.','See https://academic.oup.com/mnras/article/482/4/4570/5162857 for more information on the columns.','0');
INSERT DBObjects VALUES('mos_gaia_dr3_astrophysical_parameters','U','U','The Gaia DR3 astrophysical parameters table contains the astrophysical parameters derived for sources in Gaia DR3.','This is the main table containing the 1D astrophysical parameters produced by the Apsis processing chain developed in Gaia DPAC CU8. For more details refer to https://gea.esac.esa.int/archive/documentation/GDR3/Gaia_archive/chap_datamodel/ sec_dm_astrophysical_parameter_tables/ssec_dm_astrophysical_parameters.html.','0');
INSERT DBObjects VALUES('mos_gaia_dr3_nss_two_body_orbit','U','U','The Gaia DR3 non-single-star (NSS) two-body orbit table.','This table contains non-single-star orbital models for sources compatible with an orbital two-body solution, copied from the Gaia DR3 archive. Form more details refer to https://gea.esac.esa.int/archive/documentation/GDR3/Gaia_archiv e/chap_datamodel/sec_dm_non-- single_stars_tables/ssec_dm_nss_two_body_orbit.html.','0');
INSERT DBObjects VALUES('mos_gaia_dr3_source','U','U','The main Gaia Data Release 3 source table.','This table has an entry for every Gaia observed source as published with this data release. It contains the basic source parameters, in their final state as processed by the Gaia Data Processing and Analysis Consortium from the raw data coming from the spacecraft. For more details, refer to https://gea.esac.esa.int/ archive/documentation/GDR3/Gaia_archive/chap_datamodel/sec_dm_main_source_catalo gue/ssec_dm_gaia_source.html.','0');
INSERT DBObjects VALUES('mos_gaia_dr3_synthetic_photometry_gspc','U','U','The Gaia DR3 synthetic photometry GSPC table contains the synthetic photometry generated from the Gaia BP/RP mean spectra.','The Gaia Synthetic Photometry Catalogue (GSPC) is a catalogue of synthetic photometry generated from the Gaia BP/RP mean spectra in Data Release 3 and standardised using wide and reliable sets of external standard stars. For more details, refer to https://gea.esac.esa.int/archive/documentation/GDR3/Gaia_archi ve/chap_datamodel/sec_dm_performance_verification/ssec_dm_synthetic_photometry_g spc.html.','0');
INSERT DBObjects VALUES('mos_gaia_dr3_vari_rrlyrae','U','U','The Gaia DR3 catalogue of RR Lyrae stars. For more details, refer to https://gea.esac.esa.int/archive/documentation/GDR3/Gaia_archive/chap_datamodel/sec_dm_variability_tables/ssec_dm_vari_rrlyrae.html.','','0');
INSERT DBObjects VALUES('mos_gaia_unwise_agn','U','U','AGN identified using information from WISE and Gaia DR2 from the catalog of Shu et al. 2019.','See complete information on the columns in https://academic.oup.com/mnras/article/489/4/4741/5561523','0');
INSERT DBObjects VALUES('mos_gaiadr2_tmass_best_neighbour','U','U','The Gaia DR2 vs. 2MASS PSC crossmatch provided by the Gaia collaboration.','See https://gea.esac.esa.int/archive/documentation/GDR2/Catalogue_consolidation/ chap_cu9val_cu9val/ssec_cu9xma/sssec_cu9xma_extcat.html for complete details.','0');
INSERT DBObjects VALUES('mos_galah_dr3','U','U','The GALAH DR3 main catalogue. See https://www.galah-survey.org/dr3/table_schema/','','0');
INSERT DBObjects VALUES('mos_galex_gr7_gaia_dr3','U','U','Cross-match between the Gaia DR3 catalogue and the GALEX General Release 7 catalogue. For more details about the GALEX columns refer to https://archive.stsci.edu/prepds/gcat/gcat_dataproducts.html.','','0');
INSERT DBObjects VALUES('mos_gedr3spur_main','U','U','This table contains estimates of the [fidelity] of Gaia eDR3 astrometric solutions, a measure of the likelihood the eDR3 solution is physical rather than spurious obtained using a neural network trained on a small, hand-selected sample.','','0');
INSERT DBObjects VALUES('mos_geometric_distances_gaia_dr2','U','U','Bayesian distances from Gaia DR2 parameters from Bailer-Jones et al. 2018.','For complete details, see the original paper: https://iopscience.iop.org/article/10.3847/1538-3881/aacb21/pdf','0');
INSERT DBObjects VALUES('mos_glimpse','U','U','GLIMPSE catalog (I, II and 3-D).','See full documentation at https://irsa.ipac.caltech.edu/data/SPITZER/GLIMPSE/doc /glimpse1_dataprod_v2.0.pdf','0');
INSERT DBObjects VALUES('mos_guvcat','U','U','GALEX unique source catalog from Bianchi et al. 2017 (https://iopscience.iop.org/article/10.3847/1538-4365/aa7053/pdf).','For more details on the column descriptions see https://archive.stsci.edu/hlsp/guvcat/guvcat-column-description','0');
INSERT DBObjects VALUES('mos_hecate_1_1','U','U','The Heraklion Extragalactic Catalogue (HECATE). For more details, refer to Kovlakas et al. 2021 (https://academic.oup.com/mnras/article/506/2/1896/6309318).','','0');
