INSERT DBObjects VALUES('mos_opsdb_lco_exposure_flavor','U','U','The table contains the various types of exposures; science, dark, flat, etc. LCO version.','','0');
INSERT DBObjects VALUES('mos_panstarrs1','U','U','A copy of the PanSTARRS1-dr2 catalogue provided by E. Magnier.','Based on the internal IPP database representation maintained by IfA, U. Hawaii. Column names may differ from publically available catalogues hosted at MAST (mapping provided in column descriptions). The SDSS-V copy of this database is derived from a combination of the PS1-dr2 StackObjectThin and ObjectThin tables (https://outerspace.stsci.edu/display/PANSTARRS/PS1+Database+object+and+detectio n+tables). The catalogue contains PSF, Kron, and Aper measurements based on stacked and forced warp photometry, and expressed as fluxes, including measurements are made of low-significance detections. The average exposure (chip) measurements are expressed in magnitudes since photometry is not measured at this stage for sources with S/N < 5, so there should not be any negative fluxes. Magnitudes are on the AB system, fluxes are in Janskys. Conversion to AB mags is via: mag = 8.9 - 2.5*log10(flux).','0');
INSERT DBObjects VALUES('mos_positioner_status','U','U','Table of possible positioner statuses','','0');
INSERT DBObjects VALUES('mos_rave_dr6_gauguin_madera','U','U','Abundances from the GAUGUIN and MADERA pipelines for the RAVE DR6 data.','The abundances of the non-iron group elements (Al, Fe, and Ni) and of the alpha enhancement [alpha/Fe] derived with the pipeline GAUGUIN and MADERA input for the Radial Velocity Experiment (RAVE) DR6. See https://www.rave- survey.org/metadata/ravedr6/dr6_gauguin_madera/.','0');
INSERT DBObjects VALUES('mos_rave_dr6_xgaiae3','U','U','Position cross-match of RAVE DR6 with Gaia EDR3. See https://www.rave-survey.org/metadata/ravedr6/dr6_x_gaiaedr3/.','','0');
INSERT DBObjects VALUES('mos_revised_magnitude','U','U','This table stores magnitude information for a target. Optical magnitudes that are not selected from SDSS photometry have been converted to the SDSS system.','Entries in this revised_magnitude table only exist if there was an issue with the values in the original magnitude table. Therefore: if a carton_to_target_pk exists in this table, the values in this table should be used instead.','0');
INSERT DBObjects VALUES('mos_sagitta','U','U','Catalog of pre-main-sequence stars derived from Gaia DR2 and 2MASS from McBride et al. (2021), their Table 4.','For complete details, see the original paper: https://iopscience.iop.org/article/10.3847/1538-3881/ac2432','0');
INSERT DBObjects VALUES('mos_sagitta_edr3','U','U','Catalog of pre-main-sequence stars derived from Gaia EDR3 and 2MASS from McBride et al. (2021), their Table 5.','For complete details, see the original paper: https://iopscience.iop.org/article/10.3847/1538-3881/ac2432','0');
INSERT DBObjects VALUES('mos_sdss_apogeeallstarmerge_r13','U','U','List of APOGEE DR16 stars for RV follow-up.','','0');
INSERT DBObjects VALUES('mos_sdss_dr13_photoobj_primary','U','U','Columns from the PhotoPrimary Table of SDSS DR13.','','0');
INSERT DBObjects VALUES('mos_sdss_dr16_qso','U','U','SDSS Data Release 16 Quasar Catalog (Lyke et al. 2020).','For complete details, please see the original paper: https://ui.adsabs.harvard.edu/abs/2020ApJS..250....8L/abstract. <br> Description derived from SDSS datamodel: https://data.sdss.org/datamodel/files/BOSS_QSO/DR16Q/DR16Q_v4.html','0');
INSERT DBObjects VALUES('mos_sdss_dr16_specobj','U','U','This table contains the list of all SDSS optical spectra for a given data release, with associated parameters from the 2D and 1D pipelines for each.','The table contains both the BOSS and SDSS spectrograph data. The database representation is derived from the flat file information described here: <a href =''https://data.sdss.org/datamodel/files/SPECTRO_REDUX/specObj.html''>https://data .sdss.org/datamodel/files/SPECTRO_REDUX/specObj.html</a> Note: the order of the columns in this documentation may not match the order of the columns in the database table.','0');
INSERT DBObjects VALUES('mos_sdss_dr17_apogee_allstarmerge','U','U','The APOGEE-2 all-star merge table from DR17.','In the SDSS-IV APOGEE-2, if a star was observed in multiple fields or multiple survey modes (e.g., observed at APO vs. LCO), then the star would end up with multiple entries in the summary allStar file. This table merges all multiple entries for stars in the DR17 APOGEE allStar file. This file was primarily used for target selection for the mwm_bin_rv_long carton.','0');
INSERT DBObjects VALUES('mos_sdss_dr17_specobj','U','U','This table contains the list of all SDSS optical spectra for a given data release, with associated parameters from the 2D and 1D pipelines for each.','The table contains both the BOSS and SDSS spectrograph data. The database representation is derived from the flat file information described here: <a href =''https://data.sdss.org/datamodel/files/SPECTRO_REDUX/specObj.html''>https://data .sdss.org/datamodel/files/SPECTRO_REDUX/specObj.html</a> Note: the order of the columns in this documentation may not match the order of the columns in the database table.','0');
INSERT DBObjects VALUES('mos_sdss_dr19p_speclite','U','U','Selection of columns from the SDSS DR19 specLite file.','','0');
INSERT DBObjects VALUES('mos_sdss_id_flat','U','U','This table includes associations between sdss_id identifiers and the best matched catalogid for each catalogue cross-match.','Unlike dr20_sdss_id_stacked, this table contains multiple rows per sdss_id, one for each cross-match association. When multiple sdss_ids are associated with the same catalogid, the one with the lowest rank (rank=1) should be preferred. <br> Note: The sdss_id match was extended internally for a more recent crossmatch not yet part of the publicly released data. As such, the ra/dec_sdss_id columns may differ from the catalogid coordinates.','0');
INSERT DBObjects VALUES('mos_sdss_id_stacked','U','U','This table includes associations between sdss_id identifiers and the matched catalogids for each catalogue cross-match.','The table contains one row per sdss_id with columns for each catalogid version. However, catalogids may be associated with multiple sdss_id. dr20_sdss_id_flat is a pivoted/flattened version of this table and contains information about the preferred sdss_id for a catalogid. <br> Note: The sdss_id match was extended internally for a more recent crossmatch not yet part of the publicly released data. As such, the ra/dec_sdss_id columns may differ from the catalogid coordinates.','0');
INSERT DBObjects VALUES('mos_sdss_id_to_catalog','U','U','This table contains the best matched associations between SDSS identifiers (sdss_id, catalogid) and the unique identifiers in the parent catalogues used for SDSS cross-matches.','The format of the parent catalogue columns is <table_name>__<column_name>, where <column_name> is the primary key/unique identifier column to which to join in the dr20_<table_name> table.','0');
INSERT DBObjects VALUES('mos_sdssv_boss_conflist','U','U','The dr20_sdssv_boss_conflist table is a database representation of an','early version of the SDSS-V BOSS fieldlist data product. <br> The dr20_sdssv_boss_conflist table was used within early iterations of FPS target_selection as a way to communicate information about which SDSS-V plates had been observed by the time of target selection. This information was used to e.g. de-prioritise targets that were expected to have a good quality spectroscopic measurement before the start of SDSS-V FPS operations. <br> Caution. The dr20_sdssv_boss_conflist table should only be used in order to recreate the target_selection selection function. <br> Column descriptions are mainly derived from: https://data.sdss.org/datamodel/files/BOSS_SPECTRO_REDUX/RUN2D/platelist.html','0');
INSERT DBObjects VALUES('mos_sdssv_boss_spall','U','U','The dr20_sdssv_boss_spall table is a database representation of an early version of the SDSS-V BOSS spAll data product.','The dr20_sdssv_boss_spall table was used within early iterations of FPS target_selection as a way to communicate information about which targets had been observed in SDSS-V plates. This information was used to e.g. de-prioritise targets that were expected to have a good quality spectroscopic measurement before the start of SDSS-V FPS operations. <br> Caution. The dr20_sdssv_boss_spall table should only be used in order to recreate the target_selection selection function. <br> Column descriptions are mainly derived from: https://data.sdss.org/datamodel/files/BOSS_SPECTRO_REDUX/RUN2D/spAll.html','0');
INSERT DBObjects VALUES('mos_sdssv_plateholes','U','U','The combination of the dr20_sdssv_plateholes and dr20_sdssv_plateholes_meta tables are a database representation of the SDSS-V platelist data product (https://svn.sdss.org/public/data/sdss/platelist/trunk/).','These tables were used within early iterations of FPS target_selection as a way to communicate information about which targets had been included in SDSS-V plates. This information was used to e.g. de-prioritise targets that were expected to have a good quality spectroscopic measurement by the end of the SDSS-V plate observations. <br> The dr20_sdssv_plateholes_meta table contains meta-data for each SDSS-V plate (one record per plate), whereas the dr20_sdssv_plateholes table has one entry for each drilled hole in each SDSS-V plate. The dr20_sdssv_plateholes and dr20_sdssv_plateholes_meta tables should be joined via the yanny_uid field. <br> Mostly derived from: https://data.sdss.org/datamodel/files/PLATELIST_DIR/designs /DESIGNID6XX/DESIGNID6/plateDesign.html','0');
INSERT DBObjects VALUES('mos_sdssv_plateholes_meta','U','U','The combination of the dr20_sdssv_plateholes and dr20_sdssv_plateholes_meta','tables are a database representation of the SDSS-V platelist data <br> product (https://svn.sdss.org/public/data/sdss/platelist/trunk/). <br> These tables were used within early iterations of FPS target_selection as a way to communicate information about which targets had been included in SDSS-V plates. This information was used to e.g. de-prioritise targets that were expected to have a good quality spectroscopic measurement by the end of the SDSS-V plate observations. <br> The dr20_sdssv_plateholes_meta table contains meta-data for each SDSS-V plate (one record per plate), whereas the dr20_sdssv_plateholes table has one entry for each drilled hole in each SDSS-V plate. The dr20_sdssv_plateholes and dr20_sdssv_plateholes_meta tables should be joined via the yanny_uid field. <br> Mostly derived from: https://data.sdss.org/datamodel/files/PLATELIST_DIR/plates/ PLATEID6XX/PLATEID6/plateHoles.html','0');
INSERT DBObjects VALUES('mos_skies_v1','U','U','This table stores the positions used as blank sky regions for DR20 targetting.','The sky regions are selected by dividing the sky in tiles of HEALpix nside 32. Each tile is then subdivided in candidate regions of HEALpix nside 32768 and the pixels that meet the isolation requirements are considered valid skies. This process is repeated for a number of all-sky catalogues. See <a href=''https://sdss.org/dr20/targeting/fps/sky/''> for further details of the process by which suitable sky locations are selected in SDSS-V/FPS. This version of the skies catalog was used for v0.1 target selection. The skies_v2 catalog was used for v0.5 and subsequent target selections.','0');
INSERT DBObjects VALUES('mos_skies_v2','U','U','This table stores the positions used as blank sky regions for DR20 targetting.','The sky regions are selected by dividing the sky in tiles of HEALpix nside 32. Each tile is then subdivided in candidate regions of HEALpix nside 32768 and the pixels that meet the isolation requirements are considered valid skies. This process is repeated for a number of all-sky catalogues. See <a href=''https://sdss.org/dr20/targeting/fps/sky/''> for further details of the process by which suitable sky locations are selected in SDSS-V/FPS.','0');
INSERT DBObjects VALUES('mos_skymapper_dr2','U','U','Skymapper Data Release 2 photometry.','For detailed descriptions, please see the SkyMapper documentation: https://skymapper.anu.edu.au/table-browser/','0');
INSERT DBObjects VALUES('mos_skymapper_gaia','U','U','This catalogue contains photometric stellar parameters for 9+ million stars in common between the SkyMapper survey and Gaia DR2.','See https://skymapper.anu.edu.au/_data/sm-gaia/ for details.','0');
INSERT DBObjects VALUES('mos_supercosmos','U','U','Contains merged sources for every field in the SuperCOSMOS Science Archive (SSA). It consists of data from digitised sky survey plates taken with the UK Schmidt telescope (UKST), the ESO Schmidt, and the Palomar Schmidt.','Each field within the SSA is covered by four plates in passbands B, R and I with R being covered twice at different times. This results in four-plate multi- colour, multi-epoch data which are merged into a single source catalogue for general science exploitation. This table contains the associated merged records created from the records in table Detection, along with a full astrometric solution (including proper motions) computed from the available position measures. The most useful subset of image morphological descriptors are also propagated into this table for ease of use. <br> Derived from http://ssa.roe.ac.uk/www/SSA_TABLE_SourceSchema.html#Source','0');
INSERT DBObjects VALUES('mos_target','U','U','This table stores the targets associated with DR20 target selection cartons. Note that the targets in this table are unique, but a target can be associated with multiple cartons. That many-to-many relationship is encoded in the dr20_carton_to_target table.','','0');
INSERT DBObjects VALUES('mos_targetdb_version','U','U','List of versions associated with target selection cartons and robostategy runs.','','0');
INSERT DBObjects VALUES('mos_targeting_generation','U','U','List of SDSS-V targeting generations.','A ''targeting_generation'' describes a collection of versioned cartons, together with their robostrategy control parameters. This is a convenient way to describe the specific set of carton-versions that were used (and the way that they were treated) within any particular run of robostrategy. <br> The dr20_targeting_generation table contains all targeting_generations that were considered for observations in the timespan covered by the dr20 data release. In addition, we include the ''v0.5.3'' targeting_generation since this was the version released as part of dr20. <br> During the initial plate operations phase of SDSS-V, we did not use the robostrategy code to assign fibers to targets. However, for completeness, the ''v0.plates'' pseudo-targeting_generation has been reverse engineered in order to describe the set of carton-versions that were considered during that phase. <br> The dr20_targeting_generation table can be joined to the dr20_carton table via the dr20_targeting_generation_to_carton table. To associate a targeting_generation with a robostrategy plan, join dr20_targeting_generation to dr20_targetdb_version via the dr20_targeting_generation_to_version table. <br> Taken together, the dr20_targeting_generation, dr20_targeting_generation_to_carton and dr20_targeting_generation_to_version tables duplicate, in a database form, the robostrategy carton configuration information available via the rsconfig product (https://github.com/sdss/rsconfig).','0');
INSERT DBObjects VALUES('mos_targeting_generation_to_carton','U','U','Mapping of SDSS-V targeting generations to cartons.','A ''targeting_generation'' describes a collection of versioned cartons, together with their robostrategy control parameters. This is a convenient way to describe the specific set of carton-versions that were used (and the way that they were treated) within any particular run of robostrategy. <br> The dr20_targeting_generation_to_carton table describes a many-to-many relationship, connecting each targeting_generation to a set of entries in the dr20_carton table, as well as recording how those carton-versions were treated in the robostrategy code (i.e. the rs_stage and rs_active parameters). <br> Taken together, the dr20_targeting_generation, dr20_targeting_generation_to_carton and dr20_targeting_generation_to_version tables duplicate, in a database form, the robostrategy carton configuration information available via the rsconfig product (https://github.com/sdss/rsconfig).','0');
INSERT DBObjects VALUES('mos_targeting_generation_to_version','U','U','Mapping of targeting generations to robostrategy runs.','A ''targeting_generation'' describes a collection of versioned cartons, together with their robostrategy control parameters. This is a convenient way to describe the specific set of carton-versions that were used (and the way that they were treated) within any particular run of robostrategy. <br> The dr20_targeting_generation_to_version table describes a one-to-many relationship, connecting each robostrategy run to one targeting_generation. In general, a single target_generation can be used my more than one robostrategy run. <br> Taken together, the dr20_targeting_generation, dr20_targeting_generation_to_carton and dr20_targeting_generation_to_version tables duplicate, in a database form, the robostrategy carton configuration information available via the rsconfig product (https://github.com/sdss/rsconfig).','0');
INSERT DBObjects VALUES('mos_tess_toi','U','U','This catalog contains targets that recieved the 2 minute cadence during the TESS Mission, are TESS Objects of Interest (TOI) or Community TESS Objects of Interest (CTOI).','The contents of this catalog were derived from the MIT TESS website (https://tess.mit.edu/public/target_lists/target_lists.html) and the ExoFOP website https://exofop.ipac.caltech.edu/tess/index.php. These targets were updated on 2020-04-02.','0');
INSERT DBObjects VALUES('mos_tess_toi_v05','U','U','This catalog contains targets that received the 2 minute cadence during the TESS Mission, are TESS Objects of Interest (TOI) or Community TESS Objects of Interest (CTOI).','The contents of this catalog were derived from the MIT TESS website (https://tess.mit.edu/public/target_lists/target_lists.html) and the ExoFOP website https://exofop.ipac.caltech.edu/tess/index.php. These targets were updated on 2020-11-24.','0');
INSERT DBObjects VALUES('mos_tess_toi_v1','U','U','This catalog contains targets that received the 2 minute cadence during the TESS Mission, are TESS Objects of Interest (TOI) or Community TESS Objects of Interest (CTOI).','The contents of this catalog were derived from the MIT TESS website (https://tess.mit.edu/public/target_lists/target_lists.html) and the ExoFOP website https://exofop.ipac.caltech.edu/tess/index.php. These targets were updated on 2022-08-05.','0');
INSERT DBObjects VALUES('mos_tic_v8','U','U','The Eighth version (v8.0) of the TESS Input Catalogue (<a href=''https://outerspace.stsci.edu/display/TESS/TIC+v8+and+CTL+v8.xx+Data+Release+Notes''></a>).','','0');
INSERT DBObjects VALUES('mos_twomass_psc','U','U','2MASS point source catalog.','For full details, please see https://www.ipac.caltech.edu/2mass/releases/allsky/doc/sec2_2a.html','0');
INSERT DBObjects VALUES('mos_tycho2','U','U','Tycho-2 catalog.','For complete details, please see the original Tycho-2 documentation from Hog et al (2020) https://ui.adsabs.harvard.edu/abs/2000A%26A...355L..27H/abstract and https://www.cosmos.esa.int/web/hipparcos/tycho-2','0');
INSERT DBObjects VALUES('mos_unwise','U','U','The unWISE catalog, containing the positions and fluxes of approximately two billion objects observed by the Wide-field Infrared Survey Explorer (WISE).','For more details, see Schlafly et al. (2019). The original catalogs are hosted at https://catalog.unwise.me/catalogs.html','0');
INSERT DBObjects VALUES('mos_uvotssc1','U','U','Version 1.1 of the Swift UVOT Serendipitous Source Catalogue (UVOTSSC).','For full details, please see Page et al. (2015) at https://pos.sissa.it/233/037 and the online documentation at https://archive.stsci.edu/prepds/uvotssc/','0');
