INSERT DBObjects VALUES('mos_xmm_om_suss_4_1','U','U','The 2018 release of the XMM OM Serendipitous Ultraviolet Source Survey (XMM-SUSS4.1) Catalog.','For full details, please see https://heasarc.gsfc.nasa.gov/W3Browse/all/xmmomsuob.html and the original catalog paper (Page et al. 2012; https://academic.oup.com/mnras/article/426/2/903/976665)','0');
INSERT DBObjects VALUES('mos_xmm_om_suss_5_0','U','U','The 2021 release of the XMM OM Serendipitous Ultraviolet Source Survey (XMM-SUSS5.0) Catalog.','For full details, please see https://heasarc.gsfc.nasa.gov/W3Browse/all/xmmomsuob.html and the original catalog paper (Page et al. 2012; https://academic.oup.com/mnras/article/426/2/903/976665) and the 2021 update https://ui.adsabs.harvard.edu/abs/2021yCat.2370....0P/abstract.','0');
